"""API request handling."""


def _validate_payload(data):
    """Raise ``TypeError`` if *data* is not a valid request payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    for key in data:
        if not isinstance(key, str):
            raise TypeError("data keys must be strings")


def handle_request(data):
    """Validate an incoming API request payload and process it.

    Args:
        data: A dictionary whose keys are strings.

    Raises:
        TypeError: If ``data`` is not a dictionary or contains a non-string
            key.
    """
    _validate_payload(data)
    return process(data)

